+export function shuffledDeck(): string[] {
+  const deck = [..."23456789TJQKA"].flatMap(rank => [..."cdhs"].map(suit => rank + suit));
+  // Rejection sampling avoids modulo bias in Fisher–Yates.
+  for (let i = deck.length - 1; i > 0; i--) {
+    const bound = Math.floor(0x100000000 / (i + 1)) * (i + 1);
+    let random: number;
+    do { random = crypto.getRandomValues(new Uint32Array(1))[0]; } while (random >= bound);
+    const j = random % (i + 1);
+    [deck[i], deck[j]] = [deck[j], deck[i]];
+  }
+  return deck;
+}
+
+export function createGame(stacks: number[] = Array(6).fill(1000), deck = shuffledDeck(), id = crypto.randomUUID()): Game {
+  if (stacks.length !== 6 || stacks.some(s => !Number.isInteger(s) || s < 40 || s > 1_000_000)) {
+    throw new Error("Each of the six stacks must be a whole number from 40 to 1,000,000.");
+  }
+  if (deck.length < 17 || new Set(deck).size !== deck.length || deck.some(c => !/^[2-9TJQKA][cdhs]$/.test(c))) {
+    throw new Error("The deck must contain at least 17 distinct valid cards.");
+  }
+  const hole_cards = Array.from({ length: 6 }, (_, i) => [deck[i], deck[i + 6]]);
+  const players = stacks.map((stack, i) => {
+    const blind = i === 0 ? 20 : i === 1 ? 40 : 0;
+    return { stack: stack - blind, bet: blind, contributed: blind, folded: false, actedAt: null };
+  });
+  return {
+    input: { id, starting_stacks: [...stacks], hole_cards, board: deck.slice(12, 17), actions: [] },
+    players, street: 0, revealed: 0, currentBet: 40, minRaise: 40,
+    pending: [2, 3, 4, 5, 0, 1].filter(i => players[i].stack > 0),
+    actor: 2, complete: false,
+    log: [...hole_cards.map((cards, i) => `Player ${i + 1} is dealt ${cards.join("")}`),
+      "Player 6 is the dealer", "Player 1 posts small blind - 20 chips", "Player 2 posts big blind - 40 chips"],
+    shortActions: [],
+  };
+}
+
+export function legalActions(game: Game) {
+  const inactive = { fold: false, check: false, call: false, bet: false, raise: false, allin: false, callAmount: 0, minTo: 0, maxTo: 0 };
+  if (game.complete || game.actor === null) return inactive;
+  const player = game.players[game.actor];
+  const owed = Math.max(0, game.currentBet - player.bet);
+  const maxTo = player.bet + player.stack;
+  const reopened = player.actedAt === null || game.currentBet - player.actedAt >= game.minRaise;
+  const opponentCanCall = game.players.some((p, i) => i !== game.actor && !p.folded && p.stack > 0);
+  const canRaise = reopened && opponentCanCall && maxTo > game.currentBet;
+  return {
+    fold: true,
+    check: owed === 0,
+    call: owed > 0,
+    bet: game.currentBet === 0 && canRaise,
+    raise: game.currentBet > 0 && canRaise,
+    allin: maxTo <= game.currentBet || canRaise,
+    callAmount: Math.min(owed, player.stack),
+    minTo: Math.min(maxTo, game.currentBet + game.minRaise),
+    maxTo,
+  };
+}
+
+function revealNext(game: Game) {
+  game.street += 1;
+  const next = game.street === 1 ? 3 : game.revealed + 1;
+  const cards = game.input.board.slice(game.revealed, next).join("");
+  game.revealed = next;
+  game.log.push(`${STREETS[game.street]} cards dealt: ${cards}`);
+  game.shortActions.push(cards);
+}
+
+function finish(game: Game, showdown: boolean) {
+  if (showdown) while (game.street < 3) revealNext(game);
+  game.complete = true;
+  game.actor = null;
+  game.pending = [];
+  game.log.push(`Hand #${game.input.id} ended`);
+}
