+
+const root = join(fileURLToPath(new URL(".", import.meta.url)), "out");
+const backend = process.env.API_INTERNAL_URL ?? "http://127.0.0.1:8000";
+const types = { ".html": "text/html", ".js": "text/javascript", ".css": "text/css", ".json": "application/json", ".svg": "image/svg+xml", ".png": "image/png", ".ico": "image/x-icon", ".txt": "text/plain" };
+
+async function serve(request, response) {
+  const url = new URL(request.url, "http://localhost");
+  if (url.pathname.startsWith("/api/") || url.pathname === "/health") {
+    const target = `${backend}${url.pathname}${url.search}`;
+    const upstream = await fetch(target, { method: request.method, headers: request.headers, body: ["GET", "HEAD"].includes(request.method) ? undefined : request });
+    response.writeHead(upstream.status, Object.fromEntries(upstream.headers));
+    response.end(Buffer.from(await upstream.arrayBuffer()));
+    return;
+  }
+  const requested = normalize(join(root, decodeURIComponent(url.pathname))).replace(root, "");
+  const candidates = [join(root, requested), join(root, requested, "index.html"), join(root, requested + ".html"), join(root, "index.html")];
+  for (const candidate of candidates) {
+    if (!candidate.startsWith(root)) continue;
+    try {
+      const content = await readFile(candidate);
+      response.writeHead(200, { "content-type": types[extname(candidate)] ?? "application/octet-stream", "cache-control": "no-cache" });
+      response.end(content);
+      return;
+    } catch {}
+  }
+  response.writeHead(404); response.end("Not found");
+}
